begin;select no_plan();
create function pg_temp.tid(v text)returns uuid language sql immutable as $$select md5('chat-token-test:'||v)::uuid$$;
insert into auth.users(id,email,email_confirmed_at,is_anonymous)values(pg_temp.tid('owner'),'token@example.invalid',now(),false),(pg_temp.tid('other'),'token-other@example.invalid',now(),false);
update private.credit_settings set enabled=true;update private.provider_runtime_config set enabled=true where provider='gpt-6.1-sol';
create function pg_temp.chat_input(label text)returns jsonb language sql as $$select jsonb_build_object('requestId',pg_temp.tid(label),'operation','chat','model','gpt-6.1-sol','billing',jsonb_build_object('version',(select version from private.credit_settings),'rateVersion','synthetic-token-v1','totalMinor',150),'input',jsonb_build_object('message','Synthetic prompt'))$$;
create function pg_temp.chat(a text,i jsonb,u uuid default pg_temp.tid('owner'))returns jsonb language sql as $$select public.chat_usage_dispatch(u,a,i)$$;
select ok(not has_function_privilege('authenticated','public.chat_usage_dispatch(uuid,text,jsonb)','execute'),'browser cannot submit token usage or identity');
select throws_ok($$select pg_temp.chat('start',pg_temp.chat_input('disabled'))$$,'P0001','chat_tariff_unavailable','no default token tariffs admit new billing');
select throws_ok($$select public.credit_dispatch(pg_temp.tid('owner'),'text_start',pg_temp.chat_input('disabled-legacy'))$$,'P0001','chat_tariff_unavailable','old Web cannot bypass disabled token tariff to create fixed-price chat');
insert into private.chat_usage_versions values('synthetic-token-v1','{"model":"gpt-6.1-sol","requestModel":"gpt-6.1-sol","responseModels":["gpt-6.1-sol"],"inputPerMillionNano":"14400000000","cachedInputPerMillionNano":"720000000","outputPerMillionNano":"72000000000","markupBps":10000,"maxInputTokens":32000,"maxOutputTokens":4000,"evidence":"Synthetic offline fixture, never approved live pricing"}');
update private.chat_usage_settings set enabled=true,version='synthetic-token-v1'where model='gpt-6.1-sol';
select is(private.chat_usage_cap(private.chat_usage_config('gpt-6.1-sol')),150::bigint,'database cap matches high precision domain quote');
select throws_ok($$select pg_temp.chat('start',jsonb_set(pg_temp.chat_input('stale'),'{billing,rateVersion}','"stale"'))$$,'P0001','credit_price_changed','stale rate version cannot authorize spending');
create temporary table tok_order as select pg_temp.chat('start',pg_temp.chat_input('success'))v;
select is(pg_temp.chat('start',pg_temp.chat_input('success')),(select v from tok_order),'new token reservation is idempotent');
select is((select frozen_minor from private.credit_wallets where user_id=pg_temp.tid('owner')),150::bigint,'one exact cap reserved');
select throws_ok($$select pg_temp.chat('complete',jsonb_build_object('requestId',pg_temp.tid('success')),pg_temp.tid('other'))$$,'P0001','credit_operation_not_found','another owner cannot settle');
select public.credit_dispatch(pg_temp.tid('owner'),'text_claim',jsonb_build_object('requestId',pg_temp.tid('success')));
select is(public.openai_chat_relay(pg_temp.tid('owner'),pg_temp.tid('success'),'gpt-6.1-sol','claim')->>'maxOutputTokens','4000','provider uses frozen output budget');
select throws_ok($$select public.openai_chat_relay(pg_temp.tid('owner'),pg_temp.tid('success'),'gpt-6.1-sol','claim')$$,'P0001','relay_result_pending','unknown attempt cannot call provider twice');
select public.openai_chat_relay(pg_temp.tid('owner'),pg_temp.tid('success'),'gpt-6.1-sol','usage_result','{"content":"Saved reply","receipt":{"providerRequestId":"synthetic-r1","resolvedModel":"gpt-6.1-sol","finishReason":"stop","inputTokens":1000,"outputTokens":500,"cachedInputTokens":0,"totalTokens":1500}}');
select throws_ok($$select private.credit_settle((select(v->>'id')::uuid from tok_order),'succeeded')$$,'P0001','use_token_settlement','legacy full-cap capture cannot charge a token operation');
select is(pg_temp.chat('complete',jsonb_build_object('requestId',pg_temp.tid('success')))->>'status','succeeded','verified token reply settles');
select is((select spent_minor from private.credit_wallets where user_id=pg_temp.tid('owner')),11::bigint,'input/output components round only once, no image minimum');
select is((select available_minor from private.credit_wallets where user_id=pg_temp.tid('owner')),989::bigint,'unused cap returned');
select pg_temp.chat('complete',jsonb_build_object('requestId',pg_temp.tid('success')));
select is((select count(*)::int from private.credit_ledger where operation_id=(select(v->>'id')::uuid from tok_order)and kind='capture'),1,'settlement recovery cannot charge twice');
select throws_ok($$update private.chat_usage_versions set tariff='{}'where version='synthetic-token-v1'$$,'P0001','chat_tariff_is_immutable','reviewed tariff cannot be overwritten');
select pg_temp.chat('start',pg_temp.chat_input('missing'));
select public.credit_dispatch(pg_temp.tid('owner'),'text_claim',jsonb_build_object('requestId',pg_temp.tid('missing')));
select public.openai_chat_relay(pg_temp.tid('owner'),pg_temp.tid('missing'),'gpt-6.1-sol','claim');
select public.openai_chat_relay(pg_temp.tid('owner'),pg_temp.tid('missing'),'gpt-6.1-sol','usage_result','{"content":"Keep this prose","receipt":null}');
select is(pg_temp.chat('complete',jsonb_build_object('requestId',pg_temp.tid('missing')))->>'status','needs_review','missing usage holds instead of guessing a price');
select is((select result->>'content'from private.credit_operations where business_key='text:'||pg_temp.tid('missing')),'Keep this prose','missing usage does not lose completed prose');
select is((select frozen_minor from private.credit_wallets where user_id=pg_temp.tid('owner')),150::bigint,'missing usage preserves authorization for review');
select is(private.chat_usage_amount(private.chat_usage_config('gpt-6.1-sol'),150,'{"providerRequestId":"x","resolvedModel":"gpt-6.1-sol","finishReason":"cancelled","inputTokens":1000,"outputTokens":500,"cachedInputTokens":0,"totalTokens":1500}')->>'captureMinor','11','verified stop uses actual usage');
select is(private.chat_usage_amount(private.chat_usage_config('gpt-6.1-sol'),150,'{"providerRequestId":"x","resolvedModel":"gpt-6.1-sol","inputTokens":1000,"outputTokens":500,"cachedInputTokens":0,"totalTokens":1500}')->>'reviewReason','usage_unverified','missing outcome proof remains held');
select is(private.chat_usage_amount(private.chat_usage_config('gpt-6.1-sol'),150,'{"providerRequestId":"x","resolvedModel":"gpt-6.1-sol","finishReason":"stop","inputTokens":32001,"outputTokens":500,"cachedInputTokens":0,"totalTokens":32501}')->>'reviewReason','usage_budget_exceeded','unverified overspend never charges beyond cap');
select finish();rollback;
